WITH gaps AS (SELECT *, CASE WHEN event_time - LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM web_events), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT id, session_id, page, event_time, duration_sec, new_group_flag FROM sessionized ORDER BY duration_sec NULLS LAST
